// Procedural pixel-art texture atlas — all artwork generated by code (original designs)
import { mulberry32 } from './noise'

export const ATLAS_COLS = 8
export const ATLAS_ROWS = 5
export const TILE_PX = 16

// Tile indices in the atlas
export const TILE = {
  GRASS_TOP: 0,
  GRASS_SIDE: 1,
  DIRT: 2,
  STONE: 3,
  COBBLE: 4,
  SAND: 5,
  LOG_SIDE: 6,
  LOG_TOP: 7,
  PLANKS: 8,
  LEAVES: 9,
  GLASS: 10,
  WATER: 11,
  BRICKS: 12,
  BEDROCK: 13,
  SNOW: 14,
  GRAVEL: 15,
  GLOWSTONE: 16,
  ROSE: 17,
  DANDELION: 18,
  TALLGRASS: 19,
  COAL_ORE: 20,
  IRON_ORE: 21,
  GOLD_ORE: 22,
  DIAMOND_ORE: 23,
  CACTUS_SIDE: 24,
  CACTUS_TOP: 25,
  BED_TOP: 26,
  BED_SIDE: 27,
  CRACK: 32, // 32..39 → 8 crack stages (row 4)
} as const

type Ctx = CanvasRenderingContext2D

function pick(rnd: () => number, arr: string[]): string {
  return arr[Math.floor(rnd() * arr.length)]
}

function noiseFill(ctx: Ctx, rnd: () => number, shades: string[], w = 16, h = 16) {
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      ctx.fillStyle = pick(rnd, shades)
      ctx.fillRect(x, y, 1, 1)
    }
  }
}

function speckle(ctx: Ctx, rnd: () => number, colors: string[], count: number, w = 16, h = 16) {
  for (let i = 0; i < count; i++) {
    ctx.fillStyle = pick(rnd, colors)
    ctx.fillRect(Math.floor(rnd() * w), Math.floor(rnd() * h), 1, 1)
  }
}

// ---------- tile painters (all original artwork) ----------

const painters: Record<number, (ctx: Ctx, rnd: () => number) => void> = {
  [TILE.GRASS_TOP]: (ctx, rnd) => {
    noiseFill(ctx, rnd, ['#59a83f', '#4f9c37', '#63b247', '#479231', '#5aa63e'])
    speckle(ctx, rnd, ['#6fc353', '#3f8529'], 24)
  },
  [TILE.DIRT]: (ctx, rnd) => {
    noiseFill(ctx, rnd, ['#7a5638', '#6e4c30', '#86603f', '#634426', '#74512f'])
    speckle(ctx, rnd, ['#8d6a47', '#57391f'], 20)
  },
  [TILE.GRASS_SIDE]: (ctx, rnd) => {
    noiseFill(ctx, rnd, ['#7a5638', '#6e4c30', '#86603f', '#634426'])
    const greens = ['#59a83f', '#4f9c37', '#63b247', '#479231']
    const darks = ['#3f8529', '#356e20']
    for (let x = 0; x < 16; x++) {
      const depth = 3 + Math.floor(rnd() * 3) // 3-5px grass lip over the dirt
      ctx.fillStyle = pick(rnd, darks)
      ctx.fillRect(x, depth - 1, 1, 1) // darker fringe where grass meets dirt
      for (let y = 0; y < depth - 1; y++) {
        ctx.fillStyle = pick(rnd, greens)
        ctx.fillRect(x, y, 1, 1)
      }
      // tiny grass blades hanging down
      if (rnd() < 0.3) {
        ctx.fillStyle = pick(rnd, greens)
        ctx.fillRect(x, depth, 1, 1)
      }
    }
  },
  [TILE.STONE]: (ctx, rnd) => {
    noiseFill(ctx, rnd, ['#7e7e7e', '#767676', '#888888', '#6f6f6f'])
    speckle(ctx, rnd, ['#959595', '#646464'], 26)
    // few darker patches
    for (let i = 0; i < 5; i++) {
      const x = Math.floor(rnd() * 14), y = Math.floor(rnd() * 14)
      ctx.fillStyle = '#6a6a6a'
      ctx.fillRect(x, y, 2, 1)
      ctx.fillRect(x, y + 1, 1, 1)
    }
  },
  [TILE.COBBLE]: (ctx, rnd) => {
    noiseFill(ctx, rnd, ['#6f6f6f', '#666666', '#787878'])
    // rounded stones on a staggered grid
    const stones = ['#8b8b8b', '#828282', '#939393']
    for (let gy = 0; gy < 4; gy++) {
      for (let gx = 0; gx < 4; gx++) {
        const ox = gx * 4 + (gy % 2 === 0 ? 0 : 2)
        const oy = gy * 4
        ctx.fillStyle = pick(rnd, stones)
        for (let y = 0; y < 3; y++) {
          for (let x = 0; x < 3; x++) {
            const xx = (ox + x) % 16
            const yy = oy + y
            if (rnd() > 0.12) ctx.fillRect(xx, yy, 1, 1)
          }
        }
      }
    }
    speckle(ctx, rnd, ['#5a5a5a'], 14)
  },
  [TILE.SAND]: (ctx, rnd) => {
    noiseFill(ctx, rnd, ['#d9cf9d', '#cfc48e', '#e3daae', '#c8bd85'])
    speckle(ctx, rnd, ['#efe7c0', '#bcb078'], 22)
  },
  [TILE.GRAVEL]: (ctx, rnd) => {
    noiseFill(ctx, rnd, ['#7d7671', '#6f6862', '#8a827c', '#5f5954'])
    speckle(ctx, rnd, ['#9c948d', '#4e4844', '#867d6c'], 30)
  },
  [TILE.LOG_SIDE]: (ctx, rnd) => {
    noiseFill(ctx, rnd, ['#6a5130', '#5f482a', '#755a37'])
    for (let x = 0; x < 16; x += 2 + Math.floor(rnd() * 2)) {
      ctx.fillStyle = rnd() > 0.5 ? '#523d22' : '#4a3820'
      for (let y = 0; y < 16; y++) if (rnd() > 0.15) ctx.fillRect(x, y, 1, 1)
    }
    speckle(ctx, rnd, ['#836640'], 10)
  },
  [TILE.LOG_TOP]: (ctx, rnd) => {
    noiseFill(ctx, rnd, ['#9a7a48', '#8f7142', '#a5854f'])
    ctx.strokeStyle = '#6a5130'
    const rings = [7, 5, 3, 1]
    for (const r of rings) {
      ctx.strokeRect(8 - r + 0.5, 8 - r + 0.5, r * 2 - 1, r * 2 - 1)
    }
    ctx.fillStyle = '#b5955c'
    ctx.fillRect(7, 7, 2, 2)
  },
  [TILE.PLANKS]: (ctx, rnd) => {
    noiseFill(ctx, rnd, ['#a8834f', '#9e7a47', '#b28d57'])
    for (let y = 3; y < 16; y += 4) {
      ctx.fillStyle = '#7c5f33'
      ctx.fillRect(0, y, 16, 1)
    }
    // vertical seams, staggered
    ctx.fillStyle = '#7c5f33'
    ctx.fillRect(4, 0, 1, 3)
    ctx.fillRect(11, 4, 1, 3)
    ctx.fillRect(6, 8, 1, 3)
    ctx.fillRect(13, 12, 1, 3)
    speckle(ctx, rnd, ['#c09a60'], 12)
  },
  [TILE.LEAVES]: (ctx, rnd) => {
    ctx.clearRect(0, 0, 16, 16)
    for (let y = 0; y < 16; y++) {
      for (let x = 0; x < 16; x++) {
        if (rnd() < 0.88) {
          ctx.fillStyle = pick(rnd, ['#3c7a26', '#346c20', '#448a2c', '#2c5e1a', '#3f8229', '#4a9432'])
          ctx.fillRect(x, y, 1, 1)
        }
      }
    }
    speckle(ctx, rnd, ['#5aa63e', '#68b74a'], 12)
  },
  [TILE.GLASS]: (ctx, rnd) => {
    ctx.clearRect(0, 0, 16, 16)
    ctx.fillStyle = '#e8f6ff'
    // border
    ctx.fillRect(0, 0, 16, 1)
    ctx.fillRect(0, 15, 16, 1)
    ctx.fillRect(0, 0, 1, 16)
    ctx.fillRect(15, 0, 1, 16)
    // diagonal streaks
    ctx.fillStyle = '#d5ecf8'
    for (let i = 0; i < 5; i++) {
      ctx.fillRect(3 + i, 8 - i, 1, 1)
      ctx.fillRect(8 + i, 12 - i, 1, 1)
    }
    void rnd
  },
  [TILE.WATER]: (ctx, rnd) => {
    noiseFill(ctx, rnd, ['#3660cf', '#3059c2', '#3d6adc', '#2b53b6'])
    speckle(ctx, rnd, ['#4d7ceb', '#5d8bf2'], 16)
    // a few lighter wave streaks
    for (let i = 0; i < 4; i++) {
      const x = Math.floor(rnd() * 10)
      const y = Math.floor(rnd() * 16)
      ctx.fillStyle = '#6d95f5'
      ctx.fillRect(x, y, 3 + Math.floor(rnd() * 3), 1)
    }
  },
  [TILE.BRICKS]: (ctx, rnd) => {
    ctx.fillStyle = '#9b9b93'
    ctx.fillRect(0, 0, 16, 16)
    const brick = ['#9e4a35', '#a5523c', '#964330']
    for (let row = 0; row < 4; row++) {
      const oy = row * 4
      const offset = row % 2 === 0 ? 0 : 4
      for (let bx = -1; bx < 3; bx++) {
        const ox = bx * 8 + offset
        ctx.fillStyle = pick(rnd, brick)
        for (let y = 0; y < 3; y++) {
          for (let x = 0; x < 7; x++) {
            const xx = ox + x
            if (xx >= 0 && xx < 16) ctx.fillRect(xx, oy + y, 1, 1)
          }
        }
      }
    }
    speckle(ctx, rnd, ['#b06046'], 10)
  },
  [TILE.BEDROCK]: (ctx, rnd) => {
    noiseFill(ctx, rnd, ['#3c3c3c', '#323232', '#484848', '#282828'])
    speckle(ctx, rnd, ['#555555', '#1e1e1e'], 28)
  },
  [TILE.SNOW]: (ctx, rnd) => {
    noiseFill(ctx, rnd, ['#f2f9ff', '#eaf3fa', '#ffffff', '#e2edf5'])
    speckle(ctx, rnd, ['#d8e6f0'], 10)
  },
  [TILE.GLOWSTONE]: (ctx, rnd) => {
    noiseFill(ctx, rnd, ['#d9a63e', '#cc9a34', '#e4b449'])
    speckle(ctx, rnd, ['#ffedb8', '#f7d97e', '#c08628'], 34)
  },
  [TILE.ROSE]: (ctx, rnd) => {
    ctx.clearRect(0, 0, 16, 16)
    // stem
    ctx.fillStyle = '#2f6b1d'
    ctx.fillRect(7, 8, 1, 8)
    ctx.fillRect(6, 11, 1, 1)
    ctx.fillRect(9, 10, 1, 1)
    ctx.fillStyle = '#3c7a26'
    ctx.fillRect(6, 12, 1, 1)
    // petals
    const petals = ['#c62828', '#b71c1c', '#d32f2f']
    for (let y = 2; y < 8; y++) {
      for (let x = 5; x < 11; x++) {
        const dx = x - 7.5, dy = y - 4.5
        if (dx * dx + dy * dy < 7.5 && rnd() > 0.15) {
          ctx.fillStyle = pick(rnd, petals)
          ctx.fillRect(x, y, 1, 1)
        }
      }
    }
    ctx.fillStyle = '#7a1212'
    ctx.fillRect(7, 4, 2, 1)
    ctx.fillStyle = '#e53935'
    ctx.fillRect(6, 3, 2, 1)
    ctx.fillRect(9, 5, 1, 1)
  },
  [TILE.DANDELION]: (ctx, rnd) => {
    ctx.clearRect(0, 0, 16, 16)
    ctx.fillStyle = '#2f6b1d'
    ctx.fillRect(8, 8, 1, 8)
    ctx.fillRect(7, 12, 1, 1)
    ctx.fillStyle = '#3c7a26'
    ctx.fillRect(9, 11, 1, 1)
    const petals = ['#f4d03f', '#e8c02e', '#ffe066']
    for (let y = 3; y < 8; y++) {
      for (let x = 6; x < 11; x++) {
        const dx = x - 8, dy = y - 5
        if (dx * dx + dy * dy < 5.5 && rnd() > 0.12) {
          ctx.fillStyle = pick(rnd, petals)
          ctx.fillRect(x, y, 1, 1)
        }
      }
    }
    ctx.fillStyle = '#f9e07f'
    ctx.fillRect(7, 4, 2, 2)
  },
  [TILE.TALLGRASS]: (ctx, rnd) => {
    ctx.clearRect(0, 0, 16, 16)
    const greens = ['#4f9c37', '#59a83f', '#479231', '#63b247']
    for (let i = 0; i < 9; i++) {
      let x = 1 + Math.floor(rnd() * 14)
      const hgt = 5 + Math.floor(rnd() * 8)
      ctx.fillStyle = pick(rnd, greens)
      for (let y = 15; y > 15 - hgt; y--) {
        ctx.fillRect(x, y, 1, 1)
        if (rnd() > 0.65) x += rnd() > 0.5 ? 1 : -1
        x = Math.max(0, Math.min(15, x))
      }
    }
  },
  [TILE.COAL_ORE]: (ctx, rnd) => {
    noiseFill(ctx, rnd, ['#7e7e7e', '#767676', '#888888', '#6f6f6f'])
    // dark coal chunks
    for (let i = 0; i < 5; i++) {
      const x = 1 + Math.floor(rnd() * 12), y = 1 + Math.floor(rnd() * 12)
      const w = 2 + Math.floor(rnd() * 2), h = 2 + Math.floor(rnd() * 2)
      ctx.fillStyle = '#232323'
      ctx.fillRect(x, y, w, h)
      ctx.fillStyle = '#3a3a3a'
      ctx.fillRect(x, y, 1, 1)
      ctx.fillStyle = '#141414'
      ctx.fillRect(x + w - 1, y + h - 1, 1, 1)
    }
  },
  [TILE.IRON_ORE]: (ctx, rnd) => {
    noiseFill(ctx, rnd, ['#7e7e7e', '#767676', '#888888', '#6f6f6f'])
    for (let i = 0; i < 5; i++) {
      const x = 1 + Math.floor(rnd() * 12), y = 1 + Math.floor(rnd() * 12)
      const w = 2 + Math.floor(rnd() * 2), h = 2 + Math.floor(rnd() * 2)
      ctx.fillStyle = '#d8af93'
      ctx.fillRect(x, y, w, h)
      ctx.fillStyle = '#e8c9ae'
      ctx.fillRect(x, y, 1, 1)
      ctx.fillStyle = '#b08a6b'
      ctx.fillRect(x + w - 1, y + h - 1, 1, 1)
    }
  },
  [TILE.GOLD_ORE]: (ctx, rnd) => {
    noiseFill(ctx, rnd, ['#7e7e7e', '#767676', '#888888', '#6f6f6f'])
    for (let i = 0; i < 5; i++) {
      const x = 1 + Math.floor(rnd() * 12), y = 1 + Math.floor(rnd() * 12)
      const w = 2 + Math.floor(rnd() * 2), h = 2 + Math.floor(rnd() * 2)
      ctx.fillStyle = '#f0c53c'
      ctx.fillRect(x, y, w, h)
      ctx.fillStyle = '#ffe98a'
      ctx.fillRect(x, y, 1, 1)
      ctx.fillStyle = '#c39a20'
      ctx.fillRect(x + w - 1, y + h - 1, 1, 1)
    }
  },
  [TILE.DIAMOND_ORE]: (ctx, rnd) => {
    noiseFill(ctx, rnd, ['#7e7e7e', '#767676', '#888888', '#6f6f6f'])
    for (let i = 0; i < 4; i++) {
      const x = 1 + Math.floor(rnd() * 12), y = 1 + Math.floor(rnd() * 12)
      const w = 2 + Math.floor(rnd() * 2), h = 2 + Math.floor(rnd() * 2)
      ctx.fillStyle = '#4dd6d2'
      ctx.fillRect(x, y, w, h)
      ctx.fillStyle = '#b3f7f4'
      ctx.fillRect(x, y, 1, 1)
      ctx.fillStyle = '#2aa7a5'
      ctx.fillRect(x + w - 1, y + h - 1, 1, 1)
    }
  },
  [TILE.CACTUS_SIDE]: (ctx, rnd) => {
    noiseFill(ctx, rnd, ['#2e7d32', '#276b2b', '#358c3a', '#1f5a23'])
    // vertical ribs
    for (let x = 1; x < 16; x += 4) {
      ctx.fillStyle = '#1c5220'
      for (let y = 0; y < 16; y++) if (rnd() > 0.2) ctx.fillRect(x, y, 1, 1)
      ctx.fillStyle = '#4caf50'
      for (let y = 0; y < 16; y++) if (rnd() > 0.5) ctx.fillRect(x + 1, y, 1, 1)
    }
    // spines
    speckle(ctx, rnd, ['#e8f5c8', '#d4e3a4'], 7)
  },
  [TILE.CACTUS_TOP]: (ctx, rnd) => {
    noiseFill(ctx, rnd, ['#358c3a', '#2e7d32', '#3d9a42'])
    ctx.strokeStyle = '#1c5220'
    ctx.strokeRect(2.5, 2.5, 11, 11)
    ctx.fillStyle = '#4caf50'
    ctx.fillRect(6, 6, 4, 4)
    speckle(ctx, rnd, ['#e8f5c8'], 4)
  },
  // bed top: wooden frame + white pillow (head end) + red blanket — original design
  [TILE.BED_TOP]: (ctx, rnd) => {
    // wooden frame
    noiseFill(ctx, rnd, ['#8a6a3c', '#7c5f33', '#95754a'])
    // inner area
    ctx.fillStyle = '#a03028'
    ctx.fillRect(1, 1, 14, 14)
    // red blanket with subtle weave
    for (let y = 6; y < 15; y++) {
      for (let x = 1; x < 15; x++) {
        ctx.fillStyle = pick(rnd, ['#a03028', '#96291f', '#aa3a30'])
        ctx.fillRect(x, y, 1, 1)
      }
    }
    // fold line across blanket
    ctx.fillStyle = '#7c1d15'
    ctx.fillRect(1, 9, 14, 1)
    // white pillow at the head end
    for (let y = 2; y < 6; y++) {
      for (let x = 2; x < 14; x++) {
        ctx.fillStyle = pick(rnd, ['#f4f4f4', '#e8e8e8', '#ffffff', '#dcdcdc'])
        ctx.fillRect(x, y, 1, 1)
      }
    }
    // pillow shading
    ctx.fillStyle = '#cfcfcf'
    ctx.fillRect(2, 5, 12, 1)
    ctx.fillRect(2, 2, 12, 1)
  },
  // bed side: blanket over wooden base
  [TILE.BED_SIDE]: (ctx, rnd) => {
    noiseFill(ctx, rnd, ['#8a6a3c', '#7c5f33', '#95754a'])
    // wood grain
    for (let y = 8; y < 16; y++) {
      for (let x = 0; x < 16; x++) {
        if (rnd() > 0.7) {
          ctx.fillStyle = pick(rnd, ['#6a5130', '#5f482a'])
          ctx.fillRect(x, y, 1, 1)
        }
      }
    }
    // legs
    ctx.fillStyle = '#54401f'
    ctx.fillRect(0, 10, 3, 6)
    ctx.fillRect(13, 10, 3, 6)
    // blanket hanging over the side
    ctx.fillStyle = '#a03028'
    ctx.fillRect(0, 0, 16, 7)
    for (let y = 0; y < 7; y++) {
      for (let x = 0; x < 16; x++) {
        ctx.fillStyle = pick(rnd, ['#a03028', '#96291f', '#aa3a30'])
        if (rnd() > 0.25) ctx.fillRect(x, y, 1, 1)
      }
    }
    // white sheet stripe
    ctx.fillStyle = '#ececec'
    ctx.fillRect(0, 7, 16, 2)
  },
}

function paintCrack(ctx: Ctx, stage: number) {
  ctx.clearRect(0, 0, 16, 16)
  const rnd = mulberry32(1234 + stage * 77)
  const walks = 2 + stage
  ctx.fillStyle = 'rgba(20,16,12,0.85)'
  for (let w = 0; w < walks; w++) {
    let x = 3 + Math.floor(rnd() * 10)
    let y = 3 + Math.floor(rnd() * 10)
    const len = 5 + stage * 2 + Math.floor(rnd() * 4)
    for (let i = 0; i < len; i++) {
      ctx.fillRect(x, y, 1, 1)
      const d = rnd()
      if (d < 0.35) x++
      else if (d < 0.6) x--
      else if (d < 0.85) y++
      else y--
      x = Math.max(0, Math.min(15, x))
      y = Math.max(0, Math.min(15, y))
      if (stage > 4 && rnd() > 0.7) ctx.fillRect(Math.min(15, x + 1), y, 1, 1)
    }
  }
}

let atlasCanvas: HTMLCanvasElement | null = null
const avgColorCache = new Map<number, [number, number, number]>()

export function getAtlasCanvas(): HTMLCanvasElement {
  if (atlasCanvas) return atlasCanvas
  const cv = document.createElement('canvas')
  cv.width = ATLAS_COLS * TILE_PX
  cv.height = ATLAS_ROWS * TILE_PX
  const ctx = cv.getContext('2d')!
  ctx.imageSmoothingEnabled = false
  const total = ATLAS_COLS * ATLAS_ROWS
  for (let i = 0; i < total; i++) {
    const col = i % ATLAS_COLS
    const row = Math.floor(i / ATLAS_COLS)
    const tx = col * TILE_PX
    const ty = row * TILE_PX
    if (i >= TILE.CRACK && i < TILE.CRACK + 8) {
      const sub = document.createElement('canvas')
      sub.width = TILE_PX
      sub.height = TILE_PX
      const sctx = sub.getContext('2d')!
      paintCrack(sctx, i - TILE.CRACK)
      ctx.drawImage(sub, tx, ty)
      continue
    }
    const painter = painters[i]
    if (!painter) continue
    const sub = document.createElement('canvas')
    sub.width = TILE_PX
    sub.height = TILE_PX
    const sctx = sub.getContext('2d')!
    const rnd = mulberry32(i * 7919 + 13)
    painter(sctx, rnd)
    ctx.drawImage(sub, tx, ty)
  }
  atlasCanvas = cv
  return cv
}

/** Average color of a tile (for particles) */
export function avgColorOfTile(tile: number): [number, number, number] {
  const cached = avgColorCache.get(tile)
  if (cached) return cached
  const atlas = getAtlasCanvas()
  const ctx = atlas.getContext('2d')!
  const col = tile % ATLAS_COLS
  const row = Math.floor(tile / ATLAS_COLS)
  const data = ctx.getImageData(col * TILE_PX, row * TILE_PX, TILE_PX, TILE_PX).data
  let r = 0, g = 0, b = 0, n = 0
  for (let i = 0; i < data.length; i += 4) {
    if (data[i + 3] < 40) continue
    r += data[i]; g += data[i + 1]; b += data[i + 2]; n++
  }
  if (n === 0) n = 1
  const out: [number, number, number] = [r / n / 255, g / n / 255, b / n / 255]
  avgColorCache.set(tile, out)
  return out
}

/**
 * Tiled dirt background (dataURL) for Minecraft-style menus.
 * SSR-safe: returns '' when there is no DOM (server render).
 */
let dirtBgCache: string | null = null
export function dirtBackgroundDataURL(): string {
  if (dirtBgCache) return dirtBgCache
  if (typeof document === 'undefined') return ''
  const atlas = getAtlasCanvas()
  const S = 64
  const cv = document.createElement('canvas')
  cv.width = S
  cv.height = S
  const ctx = cv.getContext('2d')!
  ctx.imageSmoothingEnabled = false
  const col = TILE.DIRT % ATLAS_COLS
  const row = Math.floor(TILE.DIRT / ATLAS_COLS)
  ctx.drawImage(atlas, col * TILE_PX, row * TILE_PX, TILE_PX, TILE_PX, 0, 0, S, S)
  // darken like the Minecraft menu background
  ctx.fillStyle = 'rgba(0,0,0,0.62)'
  ctx.fillRect(0, 0, S, S)
  dirtBgCache = cv.toDataURL()
  return dirtBgCache
}

/** Standalone crack texture for a breaking stage (0..7) */
export function makeCrackTexture(stage: number): HTMLCanvasElement {
  const cv = document.createElement('canvas')
  cv.width = TILE_PX
  cv.height = TILE_PX
  const ctx = cv.getContext('2d')!
  paintCrack(ctx, stage)
  return cv
}

// ---------- isometric block icons for UI ----------
const iconCache = new Map<number, string>()

function drawTile(ctx: Ctx, atlas: HTMLCanvasElement, tile: number, m: [number, number, number, number, number, number]) {
  const col = tile % ATLAS_COLS
  const row = Math.floor(tile / ATLAS_COLS)
  ctx.save()
  ctx.setTransform(m[0], m[1], m[2], m[3], m[4], m[5])
  ctx.drawImage(atlas, col * TILE_PX, row * TILE_PX, TILE_PX, TILE_PX, 0, 0, TILE_PX, TILE_PX)
  ctx.restore()
}

/**
 * Pseudo-isometric cube icon (dataURL). `tiles` = [top, side].
 * cross=true renders the single tile flat (plants).
 */
export function blockIconDataURL(id: number, tiles: [number, number], cross = false): string {
  if (typeof document === 'undefined') return '' // SSR-safe: no DOM on the server
  const cached = iconCache.get(id)
  if (cached) return cached
  const S = 48
  const cv = document.createElement('canvas')
  cv.width = S
  cv.height = S
  const ctx = cv.getContext('2d')!
  ctx.imageSmoothingEnabled = false
  const atlas = getAtlasCanvas()
  if (cross) {
    ctx.drawImage(atlas, (tiles[1] % ATLAS_COLS) * TILE_PX, Math.floor(tiles[1] / ATLAS_COLS) * TILE_PX, TILE_PX, TILE_PX, 4, 4, 40, 40)
  } else {
    const k = 13 / TILE_PX // horizontal half-width scale
    const cxp = S / 2
    const topY = 5
    // top face (diamond)
    drawTile(ctx, atlas, tiles[0], [k, k * 0.5, -k, k * 0.5, cxp, topY])
    // left face
    drawTile(ctx, atlas, tiles[1], [k, k * 0.5, 0, 0.82, cxp - 13, topY + 6.5])
    // right face
    drawTile(ctx, atlas, tiles[1], [k, -k * 0.5, 0, 0.82, cxp, topY + 13])
    // shading
    ctx.fillStyle = 'rgba(0,0,0,0.32)'
    ctx.save(); ctx.setTransform(k, -k * 0.5, 0, 0.82, cxp, topY + 13); ctx.fillRect(0, 0, TILE_PX, TILE_PX); ctx.restore()
    ctx.fillStyle = 'rgba(0,0,0,0.14)'
    ctx.save(); ctx.setTransform(k, k * 0.5, 0, 0.82, cxp - 13, topY + 6.5); ctx.fillRect(0, 0, TILE_PX, TILE_PX); ctx.restore()
  }
  const url = cv.toDataURL()
  iconCache.set(id, url)
  return url
}

